import re
from typing import TYPE_CHECKING, Dict, Any, Optional, List
from abc import ABC, abstractmethod
from taf.ul.sbts.energy_saving.decorators.connection import with_connection
from taf.ul.sbts.energy_saving.core.parameter_manager import try_to_convert_to_int

if TYPE_CHECKING:
    from taf.ul.sbts.energy_saving.core.context import EnergySavingContext


class Cell(ABC):
    """Base class for all cell types (NRCELL, LNCELL)"""

    def __init__(self, context: 'EnergySavingContext'):
        self.context = context

    @property
    @abstractmethod
    def cell_name(self) -> str:
        """Type of cell (NRCELL, LNCEL)"""
        pass

    @property
    @abstractmethod
    def cell_type(self) -> str:
        """Type of cell (NR, LTE)"""
        pass

    @property
    @abstractmethod
    def bts_type(self) -> str:
        """BTS type (NRBTS, LNBTS)"""
        pass

    def build_cell_dist_name(self, mrbts_id: int, bts_id: int, cell_id: int) -> str:
        """Build cell distName"""
        return f"MRBTS-{mrbts_id}/{self.bts_type}-{bts_id}/{self.cell_name}-{cell_id}"

    def build_cell_pattern(self, mrbts_id: int = None, bts_id: int = None) -> str:
        """Build regex pattern for finding cells"""
        if mrbts_id is not None and bts_id is not None:
            return rf"MRBTS-{mrbts_id}/{self.bts_type}-{bts_id}/{self.cell_name}-(\d+)$"
        elif mrbts_id is not None:
            return rf"MRBTS-{mrbts_id}/{self.bts_type}-\d+/{self.cell_name}-(\d+)$"
        else:
            return rf"MRBTS-\d+/{self.bts_type}-\d+/{self.cell_name}-(\d+)$"

    @with_connection
    def get_cells_info(self, timeout: int = 60, connection=None):
        """Get cell information"""
        return self.context.admin.get_cells_info(cell_type=self.cell_type.lower(), timeout=timeout,
                                                 connection=connection)

    @with_connection
    def get_cells_statuses(self, timeout: int = 60, connection=None) -> Dict[int, Dict]:
        cells_statuses = {}
        cells_info = self.get_cells_info(timeout=timeout, connection=connection)
        for cell_info in cells_info:
            cell_state = {**cell_info["status"], "energySavingState": cell_info["energySavingState"]}
            cells_statuses[self.get_cell_configuration_id(cell_info)] = cell_state

        return cells_statuses

    def get_cell_configuration_id(self, cell_info: Dict) -> Optional[int]:
        """Extract cell configuration ID from cell info"""
        pattern = rf".+(?:{self.cell_name})-(\d+)$"
        dist_name = cell_info["id"]["configuration"]
        match = re.search(pattern, dist_name)
        return int(match.group(1)) if match else None

    def get_existing_cell_ids_from_scf(self, xml_scf, mrbts_id: int = None, bts_id: int = None) -> List[int]:
        """
        Get existing cell IDs from SCF

        Args:
            xml_scf: SCF XML object
            mrbts_id: Optional specific MRBTS ID
            bts_id: Optional specific BTS ID
        Returns:
            List of cell IDs
        """
        pattern = self.build_cell_pattern(mrbts_id, bts_id)
        return self.context.scf_manager.get_ids_by_pattern(xml_scf, pattern)

    def get_existing_cell_dist_names_from_scf(self, xml_scf, mrbts_id: int = None, bts_id: int = None) -> List[str]:
        """
        Get existing cell distNames from SCF

        Args:
            xml_scf: SCF XML object
            mrbts_id: Optional specific MRBTS ID
            bts_id: Optional specific BTS ID
        Returns:
            List of cell distNames
        """
        pattern = self.build_cell_pattern(mrbts_id, bts_id)
        return self.context.scf_manager.get_distnames_by_pattern(xml_scf, pattern)

    def get_filtered_cells_by_params(self, xml_scf, filters: List[Dict[str, Any]]):
        """
        Filter cells by a list of rules.
        Each filter entry: {"param": "dot.path", "validation": <callable|value|None>}
        Examples:
          {"param": "zeroCorrelationZoneConfig", "validation": 13}
          {"param": "a1MeashoSsbRsrp.a1ThresholdhoSsbRsrp", "validation": lambda v: int(v) >= 35}
          {"param": "a1MeashoSsbRsrp.a1HysteresishoSsbRsrp", "validation": True}
          {"param": "a1MeashoSsbRsrp.a1ThresholdhoSsbRsrp"}  # just presence
        Returns list of distNames matching all (AND) filters.
        """
        distnames = self.get_existing_cell_dist_names_from_scf(xml_scf)
        if not filters:
            return distnames

        matched = []
        for dn in distnames:
            params = self.context.scf_manager.get_params_from_managed_object(xml_scf, dn)
            if not isinstance(params, dict):
                continue
            if self._cell_matches_filters(params, filters):
                matched.append(dn)
        return matched

    def _cell_matches_filters(self, params_dict: Dict[str, Any], filters: List[Dict[str, Any]]) -> bool:
        for flt in filters:
            path = flt.get("param")
            if not path:
                continue  # skip malformed entry
            val = flt.get("validation")
            values = self._extract_values(params_dict, path)
            if not values:
                return False  # path not found or no leaves

            if callable(val):
                ok = any(val(try_to_convert_to_int(value)) for value in values)
            elif val is None:
                # just presence is enough
                ok = True
            else:
                expected = str(val).lower()
                ok = any(str(value).lower() == expected for value in values)

            if not ok:
                return False
        return True

    def _extract_values(self, data, path: str):    # noqa: C901
        """
        Return list of leaf values for a dot-path.
        If a list is encountered along the way – iterate all elements.
        Skip dict/list structures if the path ends before a leaf.
        """
        segments = path.split('.')

        def traverse(nodes, depth: int):    # noqa: C901
            if depth == len(segments):
                leaves = []
                for n in nodes:
                    if isinstance(n, (list, dict)):
                        continue
                    leaves.append(n)
                return leaves

            key = segments[depth]
            next_nodes = []

            for node in nodes:
                if isinstance(node, dict):
                    if key not in node:
                        continue
                    val = node[key]
                    if isinstance(val, list):
                        next_nodes.extend(val)
                    else:
                        next_nodes.append(val)

                elif isinstance(node, list):
                    for item in node:
                        if isinstance(item, dict) and key in item:
                            val = item[key]
                            if isinstance(val, list):
                                next_nodes.extend(val)
                            else:
                                next_nodes.append(val)
                # ignore other types

            if not next_nodes:
                return []
            return traverse(next_nodes, depth + 1)

        return traverse([data], 0)

    def __repr__(self):
        return f"{self.__class__.__name__}(context={self.context.connection_alias})"
